class TransformerBlock28(eqx.Module):
    norm1: eqx.nn.LayerNorm
    norm2: eqx.nn.LayerNorm
    qkv: eqx.nn.Linear
    proj: eqx.nn.Linear
    fc1: eqx.nn.Linear
    fc2: eqx.nn.Linear

    def __init__(self, dm28, dff28, key):
        self.norm1 = eqx.nn.LayerNorm(dm28)
        self.norm2 = eqx.nn.LayerNorm(dm28)
        self.qkv = eqx.nn.Linear(dm28, dm28 * 3, key=key)
        self.proj = eqx.nn.Linear(dm28, dm28, key=key)
        self.fc1 = eqx.nn.Linear(dm28, dff28, key=key)
        self.fc2 = eqx.nn.Linear(dff28, dm28, key=key)

    def __call__(self, x: Float[Array, "seq28 dm28"]):
        h = jax.vmap(self.norm1)(x)
        qkv = jax.vmap(self.qkv)(h)
        q, k, v = jnp.split(qkv, 3, axis=-1)
        scores = q @ jnp.transpose(k)
        attn = jax.nn.softmax(scores, axis=-1)
        ctx = attn @ v
        ctx = jax.vmap(self.proj)(ctx)
        x = x + ctx
        h = jax.vmap(self.norm2)(x)
        h = jax.nn.gelu(jax.vmap(self.fc1)(h))
        h = jax.vmap(self.fc2)(h)
        x = x + h
        return x


class GRUCell28(eqx.Module):
    wz_x: eqx.nn.Linear
    wz_h: eqx.nn.Linear
    wh_x: eqx.nn.Linear
    wh_h: eqx.nn.Linear

    def __init__(self, isz28, hsz28, key):
        self.wz_x = eqx.nn.Linear(isz28, hsz28, key=key)
        self.wz_h = eqx.nn.Linear(hsz28, hsz28, key=key)
        self.wh_x = eqx.nn.Linear(isz28, hsz28, key=key)
        self.wh_h = eqx.nn.Linear(hsz28, hsz28, key=key)

    def step(
        self,
        h: Float[Array, "hsz28"],
        x: Float[Array, "isz28"],
    ) -> Float[Array, "hsz28"]:
        zx = self.wz_x(x)
        zh = self.wz_h(h)
        z = jax.nn.sigmoid(zx + zh)
        hx = self.wh_x(x)
        hh = self.wh_h(h)
        h_tilde = jnp.tanh(hx + hh)
        h_new = (1 - z) * h + z * h_tilde
        return h_new


def numpy_soup_28(
    a: Float[Array, "b28 n28 d28"],
    w: Float[Array, "d28 k28"],
):
    y = a @ w
    flat = y.reshape(-1)
    tot = flat.sum()
    m = jnp.mean(y, axis=1)
    s = jnp.stack([m, m, m])
    c = jnp.concatenate([y, y], axis=1)
    t = jnp.transpose(y, (2, 0, 1))
    e = jnp.expand_dims(m, axis=-1)
    sq = jnp.squeeze(e, axis=-1)
    br = jnp.broadcast_to(sq, (4, "b28", "k28"))
    ti = jnp.tile(m, (2, 1))
    z = jnp.zeros((3, 5))
    o = jnp.ones_like(y)
    wh = jnp.where(y > 0, y, o)
    p = jnp.pad(z, ((1, 1), (2, 2)))
    cs = jnp.cumsum(y, axis=0)
    st = jnp.vstack([z, z])
    return tot, s, c, t, br, ti, wh, p, cs, st


def indexing_soup_28(
    x: Float[Array, "b28 s28 h28 d28"],
):
    first = x[0]
